'use strict';
const baseRender=render;
const evtKey=()=>Hive.eventKey(state),memberName=m=>m.name;
const eventTitle=()=>`BT ${state.operations.trap} · ${state.operations.date} · ${state.settings['time'+state.operations.trap]} UTC`;
render=function(){Hive.migrate(state);Hive.syncMapCoordinates(state);baseRender();renderEventBar();renderAttendance();renderQueueTabs();};
function renderEventBar(){const o=state.operations;$('#eventBar').innerHTML=`<div class="event-context"><span class="eyebrow">EVENT</span><label>BT date (UTC)<input id="eventDate" type="date" value="${esc(o.date)}" required></label><label>Trap<select id="eventTrap"><option value="1" ${o.trap===1?'selected':''}>BT 1 · ${esc(state.settings.time1)} UTC</option><option value="2" ${o.trap===2?'selected':''}>BT 2 · ${esc(state.settings.time2)} UTC</option></select></label><div class="event-step"><button id="prevBT" aria-label="Previous BT, two days earlier">←</button><button id="nextBT" aria-label="Next BT, two days later">→</button></div></div>`;$('#eventDate').onchange=e=>{if(e.target.value)commit(()=>state.operations.date=e.target.value)};$('#prevBT').onclick=()=>commit(()=>state.operations.date=Hive.shiftEventDate(o.date,-2));$('#nextBT').onclick=()=>commit(()=>state.operations.date=Hive.shiftEventDate(o.date,2));$('#eventTrap').onchange=e=>{activeTrap=e.target.value;$$('#trapTabs button').forEach(b=>b.classList.toggle('active',b.dataset.trap===activeTrap));commit(()=>{state.operations.trap=+activeTrap;state.operations.rosterGroup=+activeTrap});if(page==='map')fit()}}
function openBulk(text='',group=state.operations.rosterGroup){openModal(`<div class="eyebrow">ROSTER IMPORT</div><h2>Add or update players</h2><label>Add / update in<select id="bulkGroup"><option value="1" ${group===1?'selected':''}>BT 1 players</option><option value="2" ${group===2?'selected':''}>BT 2 players</option><option value="0" ${group===0?'selected':''}>Other players</option></select></label><p>Use <strong>[alliance] username, player ID, code</strong>.</p><div class="notice">f / Frequently · s / Sometimes · r / Rarely · u / Unknown. A blank final code also means Unknown. Codes set a manual fallback only; attendance percentages take over from the first completed eligible BT list.</div><textarea id="bulkInput" rows="8" aria-label="Bulk roster" placeholder="[LUN] Caroline, 123456789, f\n[LUN] 별빛, 987654321, ">${esc(text)}</textarea><div class="actions"><button class="primary" id="bulkPreview">Review roster</button></div><p>Roster imports do not record attendance.</p>`);$('#bulkPreview').onclick=()=>{const raw=$('#bulkInput').value,rows=Hive.reviewBulk(state,raw);if(!rows.length||rows.length>500){toast('Enter between 1 and 500 roster lines.');return}reviewRoster(rows,raw,+$('#bulkGroup').value)}}
function reviewRoster(rows,raw,group){openModal(`<div class="eyebrow">REVIEW ROSTER</div><h2>${rows.filter(r=>!r.error).length} readable entries.</h2><p>Player IDs preserve attendance history. Destination: <strong>${group?'BT '+group+' players':'Other players'}</strong>. Existing cities are unassigned if the group changes.</p><div class="preview-list bulk-preview">${rows.map((r,i)=>r.error?`<div class="preview-item invalid"><strong>Line ${r.line}: ${esc(r.error)}</strong><small>${esc(r.raw)}</small></div>`:`<div class="preview-item"><strong>${esc(r.name)}</strong><small>ID ${esc(r.playerId)} · ${Hive.frequencyLabels[r.kind]}</small>${r.warning?`<small class="review-warning">${esc(r.warning)}</small>`:''}<div class="two"><label>Action<select data-action="${i}"><option value="new" ${r.action==='new'?'selected':''}>Add new</option>${r.candidates.length?`<option value="update" ${r.action==='update'?'selected':''}>Update existing</option>`:''}<option value="skip" ${r.action==='skip'?'selected':''}>Skip</option></select></label>${r.candidates.length?`<label>Existing record<select data-target="${i}"><option value="">Choose player…</option>${r.candidates.map(m=>`<option value="${esc(m.id)}" ${r.target===m.id?'selected':''}>${esc(m.name)} · ${esc(m.playerId||'No ID yet')}</option>`).join('')}</select></label>`:''}</div></div>`).join('')}</div><div class="actions"><button class="primary" id="bulkApply" ${rows.some(r=>r.error)?'disabled':''}>Apply reviewed roster</button><button id="bulkBack">Edit list</button></div>`);$('#bulkBack').onclick=()=>openBulk(raw,group);$('#bulkApply').onclick=()=>{for(const [i,r]of rows.entries()){if(r.error)continue;r.action=$(`[data-action="${i}"]`).value;r.target=$(`[data-target="${i}"]`)?.value||''}try{const next=Hive.applyBulk(state,rows,()=>crypto.randomUUID(),group);commit(()=>state=next);closeModal();toast('Roster saved. No event attendance changed.')}catch(e){toast(e.message)}}}
$('#bulkMembers').onclick=()=>openBulk();$('#importBtn').onclick=()=>openBulk();$('#importBtn').textContent='Paste roster';
function renderOfficerMembers(){const q=$('#memberSearch').value.toLowerCase(),f=$('#memberFilter').value;const ms=state.members.filter(m=>(memberName(m)+' '+m.playerId).toLowerCase().includes(q)).filter(m=>f==='all'||f==='unassigned'&&!m.slot||f==='0'&&m.trap===0||String(m.trap)===f&&Hive.attendanceStats(state,m,+f).kind==='regular');$('#memberList').innerHTML=ms.map(m=>`<article class="officer-member"><button class="member-card" data-officer-id="${esc(m.id)}"><span class="avatar">${esc(m.name.slice(0,1))}</span><span><strong>${esc(memberName(m))}${m.locked?' ⌑':''}</strong><small>ID ${esc(m.playerId||'Not entered')} · ${esc(slotLabel(m.slot))}</small><span class="pill">${esc(frequencyBadge(m,m.trap))}</span></span></button></article>`).join('')||'<div class="empty-state">No players match. Use Bulk roster to add names and player IDs.</div>';$$('[data-officer-id]').forEach(b=>b.onclick=()=>memberDetail(b.dataset.officerId))}
renderMembers=renderOfficerMembers;
const baseQueue=renderQueue;renderQueue=function(){baseQueue();$('#activeStat').textContent=state.members.filter(m=>Hive.attendanceStats(state,m,m.trap).kind==='regular').length;};
function memberDetail(id){const m=state.members.find(m=>m.id===id);openModal(`<div class="eyebrow">OFFICER PLAYER RECORD</div><h2>${esc(memberName(m))}</h2><p>ID ${esc(m.playerId||'Not entered')} · ${esc(slotLabel(m.slot))}</p><div class="notice">BT 1: ${esc(frequencyBadge(m,1))}<br>BT 2: ${esc(frequencyBadge(m,2))}</div><p>Percentages use complete, eligible records. Partial lists do not record absences.</p><div class="actions"><button class="primary" id="editM">Edit player</button><button id="personalM">Copy move instructions</button><button id="locateM">Show city</button><button id="moveM" ${m.locked?'disabled':''}>Move city</button><button id="lockM">${m.locked?'Unlock':'Lock city'}</button><button id="attendanceM">Attendance history</button><button id="removeCity" class="danger" ${m.locked||!m.slot?'disabled':''}>Remove from map</button></div>`);$('#removeCity').onclick=()=>{const next=Hive.removeMapObject(state,{memberId:id});commit(()=>state=next);closeModal();toast('City removed. Player kept in the queue.')};$('#editM').onclick=()=>memberForm(m);$('#personalM').onclick=()=>officerInstructions(m);$('#locateM').onclick=()=>locateMember(m);$('#moveM').onclick=()=>{selectedMember=id;setTool('move');closeModal();moveTarget=id;navigate('map');toast('Tap an empty city slot at BT '+m.trap)};$('#lockM').onclick=()=>{commit(()=>m.locked=!m.locked);memberDetail(id)};$('#attendanceM').onclick=()=>{const logs=Object.values(state.attendanceLog.sessions).filter(r=>r.eligible.includes(id)||r.attended.includes(id)).sort((a,b)=>b.date.localeCompare(a.date));openModal(`<h2>${esc(m.name)} · Attendance</h2><div class="sheet-list">${logs.map(r=>`<div class="notice">BT ${r.trap} · ${esc(r.date)} · ${r.attended.includes(id)?'Attended':r.complete?'Not in completed list':'Not yet recorded'}${r.complete?'':' · Partial'}</div>`).join('')||'<p>No recorded sessions yet.</p>'}</div>`)}}
function trackFor(m){return state.operations.tracking[evtKey()]?.[m.id]||{}}
function officerInstructions(m){const text=Hive.relocationInstruction(state,m);openModal(`<div class="eyebrow">COPY FOR THE PLAYER</div><h2>${esc(memberName(m))}</h2><textarea rows="7" readonly>${esc(text)}</textarea><div class="actions"><button class="primary" id="copyMove">Copy move instructions</button><button id="markSent">${trackFor(m).sentText===text?'Marked sent ✓':'Mark sent'}</button><button id="instructionCity">Show city</button></div>`);$('#copyMove').onclick=()=>copy(text);$('#markSent').onclick=()=>{commit(()=>{const t=state.operations.tracking[evtKey()]||(state.operations.tracking[evtKey()]={});(t[m.id]||(t[m.id]={})).sentText=text});officerInstructions(m)};$('#instructionCity').onclick=()=>locateMember(m)}
function renderOfficerMoves(){const ms=state.members.filter(m=>m.slot);$('#moveList').innerHTML=`<div class="notice">Move checklist. ${state.settings.verified?'Coordinate mapping marked verified.':'Verify map coordinates before asking players to teleport.'}</div>`+ms.map(m=>`<div class="move-row"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(memberName(m))}</strong><small>${esc(slotLabel(m.slot))}</small><span class="pill">${trackFor(m).sentText===Hive.relocationInstruction(state,m)?'Instructions sent':trackFor(m).sentText?'Instructions changed':'Not marked sent'}</span></div><div class="checks"><label class="check"><input type="checkbox" data-relocated="${esc(m.id)}" ${m.confirmed?'checked':''}> Move confirmed</label><label class="check"><input type="checkbox" data-officer-verified="${esc(m.id)}" ${m.verified?'checked':''}> Position verified</label></div><button data-instructions="${esc(m.id)}">Copy instructions</button></div>`).join('');$$('[data-relocated]').forEach(el=>el.onchange=()=>commit(()=>state.members.find(m=>m.id===el.dataset.relocated).confirmed=el.checked));$$('[data-officer-verified]').forEach(el=>el.onchange=()=>commit(()=>state.members.find(m=>m.id===el.dataset.officerVerified).verified=el.checked));$$('[data-instructions]').forEach(b=>b.onclick=()=>officerInstructions(state.members.find(m=>m.id===b.dataset.instructions)))}
renderMoves=renderOfficerMoves;
function renderAttendance(){const o=state.operations,r=Hive.attendanceSession(state),eligible=r?.eligible||state.members.filter(m=>m.trap===o.trap).map(m=>m.id),attended=r?.attended||[],completed=Object.values(state.attendanceLog.sessions).filter(x=>x.trap===o.trap&&x.complete).length;$('#attendanceSummary').innerHTML=`<div class="notice"><strong>Bear Trap ${o.trap} · ${attendanceDateLabel(o.date,true)} · ${esc(state.settings['time'+o.trap])} UTC</strong></div><div class="stats"><div><span>Attendees</span><strong>${attended.length}</strong></div><div><span>List status</span><strong>${r?.complete?'Complete':r?'Partial':'Not recorded'}</strong></div><div><span>Completed BT ${o.trap} lists</span><strong>${completed}</strong></div><div class="policy-stat"><span>Event rhythm</span><strong>Every 2 days</strong></div></div>${Hive.expectedEventDate(state,o.date,o.trap)?'':'<div class="notice">Outside the two-day schedule. Record a rescheduled event here or update Frequency rules.</div>'}`;
$('#attendanceSession').innerHTML=`<section class="card"><div class="card-heading"><div><span class="eyebrow">${esc(eventTitle())}</span><h2>${r?.complete?'Complete attendance list':'Saved attendees'}</h2></div><button id="manageSession">Review list & eligibility</button></div><div class="attendee-chips">${attended.map(id=>{const m=state.members.find(m=>m.id===id);return m?`<span class="pill">${esc(m.name)}</span>`:''}).join('')||'<p class="muted">No attendees saved for this BT yet.</p>'}</div><p>${eligible.length} eligible players. Only complete lists affect percentages. Added lists are deduplicated.</p></section>`;$('#manageSession').onclick=()=>manageSession();const logs=Object.values(state.attendanceLog.sessions).filter(x=>x.trap===o.trap).sort((a,b)=>b.date.localeCompare(a.date));$('#attendanceHistory').innerHTML=logs.map(x=>`<button class="history-row" data-session-date="${esc(x.date)}"><strong>${esc(x.date)} · BT ${x.trap}</strong><span>${x.attended.length} attended / ${x.eligible.length} eligible</span><span class="pill">${x.complete?'Complete':'Partial'}</span></button>`).join('')||'<div class="empty-state">No attendance history. Type or paste names to record your first BT.</div>';$$('[data-session-date]').forEach(b=>b.onclick=()=>{commit(()=>state.operations.date=b.dataset.sessionDate);manageSession()})}
$('#pasteAttendees').onclick=()=>openAttendanceEntry();$('#reviewSavedAttendees').onclick=()=>manageSession();

function attendanceDateLabel(date,year=false){return new Date(date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'long',...(year?{year:'numeric'}:{}),timeZone:'UTC'})}
function attendanceDestination(){return `BT${state.operations.trap} · ${attendanceDateLabel(state.operations.date)}`}
function openAttendanceEntry(text=''){openModal(`<div class="eyebrow">WHO WAS THERE · ${esc(state.settings['time'+state.operations.trap])} UTC</div><h2>Add attendees · BT${state.operations.trap} · ${attendanceDateLabel(state.operations.date,true)}</h2><p>Search and select a player, or paste one name or ID per line.</p><label>Find a player<input id="attendeeLookup" autocomplete="off" placeholder="Start typing a username…"></label><div id="attendeeSuggestions" class="sheet-list" role="listbox" aria-label="Matching players"></div><div id="selectedAttendeeChips" class="attendee-chips"></div><label>Attendee names<textarea id="attendanceEntryText" rows="7" placeholder="chaz\nCaroline\n123456789">${esc(text)}</textarea></label><div class="actions"><button class="primary" id="matchEntry">Review attendees</button></div>`);const picked=new Set();const showPicked=()=>{$('#selectedAttendeeChips').innerHTML=[...picked].map(id=>{const m=state.members.find(m=>m.id===id);return`<button class="pill" data-picked="${esc(id)}">${esc(m.name)} ×</button>`}).join('');$$('[data-picked]').forEach(b=>b.onclick=()=>{picked.delete(b.dataset.picked);showPicked()})};$('#attendeeLookup').oninput=()=>{const query=$('#attendeeLookup').value.trim();if(!query){$('#attendeeSuggestions').innerHTML='';return}const rows=Hive.reviewAttendees(state,query),candidates=rows[0]?.candidates||[];$('#attendeeSuggestions').innerHTML=candidates.map((c,i)=>{const m=state.members.find(m=>m.id===c.id);return`<button role="option" data-suggest-attendee="${esc(c.id)}">${esc(m.name)}<small class="muted">ID ${esc(m.playerId||'not entered')} · ${i===0?'Closest match · ':''}${c.exact?'Exact match':'Similar name'}</small></button>`}).join('')||'<p class="muted">No close match. Paste the exact name or player ID.</p>';$$('[data-suggest-attendee]').forEach(b=>b.onclick=()=>{picked.add(b.dataset.suggestAttendee);showPicked();$('#attendeeLookup').value='';$('#attendeeSuggestions').innerHTML='';$('#attendeeLookup').focus()})};$('#matchEntry').onclick=()=>{const ids=[...picked].map(id=>state.members.find(m=>m.id===id)?.playerId||state.members.find(m=>m.id===id)?.name).filter(Boolean);const query=$('#attendeeLookup').value.trim();reviewAttendanceText([$('#attendanceEntryText').value,...ids,query].filter(Boolean).join('\n'))};$('#attendeeLookup').focus()}
function attendanceReceipt(){const r=Hive.attendanceSession(state);$('#attendanceSavedReceipt').textContent=`Saved ${r?.attended.length||0} ${r?.attended.length===1?'attendee':'attendees'} · ${attendanceDestination()} · ${r?.complete?'Complete':'Partial list'}`;$('#attendanceSavedReceipt').classList.remove('hidden');$('#attendanceSession').scrollIntoView?.({behavior:'smooth',block:'center'})}
function reviewAttendanceText(text){const rows=Hive.reviewAttendees(state,text);if(!rows.length||rows.length>500){toast('Enter between 1 and 500 participant lines.');return}openModal(`<div class="eyebrow">EVENT ATTENDANCE · ${esc(eventTitle())}</div><h2>Confirm attendees · ${esc(attendanceDestination())}</h2><p>Exact matches are selected. Confirm similar names. Unresolved lines are skipped; duplicates count once.</p><div class="preview-list bulk-preview">${rows.map((r,i)=>`<div class="preview-item"><strong>${esc(r.raw)}</strong><label>Roster match<select data-attendee-match="${i}"><option value="">Ignore / unresolved</option>${r.candidates.map(c=>{const m=state.members.find(m=>m.id===c.id);return`<option value="${esc(c.id)}" ${r.target===c.id?'selected':''}>${esc(m.name)} · ID ${esc(m.playerId||'not entered')} · ${Math.round(c.score*100)}% text similarity</option>`}).join('')}<optgroup label="All players">${state.members.map(m=>`<option value="${esc(m.id)}">${esc(m.name)} · ID ${esc(m.playerId||'not entered')}</option>`).join('')}</optgroup></select></label>${r.target?'':'<small class="review-warning">Confirm this suggestion before saving.</small>'}</div>`).join('')}</div><label class="check"><input id="rememberAliases" type="checkbox"> Remember confirmed spellings for future suggestions</label><label>Save state<select id="attendanceSaveState"><option value="partial">Partial list · listed attendees only</option><option value="complete">Complete list · unlisted eligible players count as absent</option></select></label><div id="attendanceSaveExplanation" class="notice">The list is partial. Nobody else is marked absent.</div><div class="actions"><button class="primary" id="saveMatched"></button><button id="backToText">Edit names</button></div>`);const update=()=>{const ids=new Set($$('[data-attendee-match]').map(el=>el.value).filter(Boolean));$('#saveMatched').textContent=`Save ${attendeeLabel(ids.size)} to ${attendanceDestination()}`;$('#saveMatched').disabled=!ids.size;$('#attendanceSaveExplanation').textContent=$('#attendanceSaveState').value==='complete'?'After saving these matches, review the eligible roster and confirm the complete list.':'This saves a partial list. Nobody else is marked absent.'};$$('[data-attendee-match]').forEach(el=>el.onchange=update);$('#attendanceSaveState').onchange=update;update();$('#backToText').onclick=()=>openAttendanceEntry(text);$('#saveMatched').onclick=()=>{const aliases=[],selected=[];for(const [i,r]of rows.entries()){const id=$(`[data-attendee-match="${i}"]`).value;if(id){selected.push(id);if($('#rememberAliases').checked&&r.name)aliases.push({id,name:r.name})}}try{const previous=Hive.attendanceSession(state),completeRequest=$('#attendanceSaveState').value==='complete';const next=Hive.saveAttendanceSession(state,{date:state.operations.date,trap:state.operations.trap,selected,complete:false,eligible:previous?.eligible,aliases});commit(()=>state=next);closeModal();attendanceReceipt();if(completeRequest)manageSession(true)}catch(e){toast(e.message)}}}
function manageSession(wantComplete=false){const r=Hive.attendanceSession(state),eligible=new Set(r?.eligible||state.members.filter(m=>m.trap===state.operations.trap).map(m=>m.id)),attended=new Set(r?.attended||[]);openModal(`<div class="eyebrow">SESSION REVIEW · ${esc(eventTitle())}</div><h2>Review attendees and eligibility</h2><p>Eligible players had the opportunity to attend. Exclude new recruits and other-trap players as needed. Absence counts only when this list is complete.</p><div class="preview-list"><table class="attendance-review"><thead><tr><th>Player</th><th>Eligible</th><th>Attended</th></tr></thead><tbody>${state.members.map(m=>`<tr><td>${esc(memberName(m))}</td><td><input type="checkbox" data-eligible="${esc(m.id)}" aria-label="${esc(m.name)} eligible" ${eligible.has(m.id)?'checked':''}></td><td><input type="checkbox" data-attended="${esc(m.id)}" aria-label="${esc(m.name)} attended" ${attended.has(m.id)?'checked':''}></td></tr>`).join('')}</tbody></table></div><label class="check"><input id="sessionComplete" type="checkbox" ${r?.complete||wantComplete?'checked':''}> This list is complete. Unlisted eligible players did not attend.</label><div class="actions"><button class="primary" id="saveSessionReview">Save ${attendeeLabel(r?.attended.length||0)} to ${esc(attendanceDestination())}</button>${r?'<button class="danger" id="deleteSession">Delete this record</button>':''}</div>`);const countSession=()=>{$('#saveSessionReview').textContent=`Save ${attendeeLabel($$('[data-attended]').filter(x=>x.checked).length)} to ${attendanceDestination()}`};$$('[data-attended]').forEach(el=>el.onchange=()=>{if(el.checked)$(`[data-eligible="${el.dataset.attended}"]`).checked=true;countSession()});$$('[data-eligible]').forEach(el=>el.onchange=()=>{if(!el.checked)$(`[data-attended="${el.dataset.eligible}"]`).checked=false;countSession()});countSession();$('#saveSessionReview').onclick=()=>{const selected=$$('[data-attended]').filter(x=>x.checked).map(x=>x.dataset.attended),eligible=$$('[data-eligible]').filter(x=>x.checked).map(x=>x.dataset.eligible);try{const next=Hive.saveAttendanceSession(state,{date:state.operations.date,trap:state.operations.trap,selected,eligible,complete:$('#sessionComplete').checked,replace:true});commit(()=>state=next);closeModal();attendanceReceipt()}catch(e){toast(e.message)}};if(r)$('#deleteSession').onclick=()=>{openModal('<h2>Delete this BT record?</h2><p>Frequency will be recalculated without this event. Undo remains available.</p><button class="danger" id="confirmDeleteSession">Delete record</button>');$('#confirmDeleteSession').onclick=()=>{commit(()=>delete state.attendanceLog.sessions[evtKey()]);closeModal()}}}
$('#attendanceSettings').onclick=()=>{const c=state.attendanceLog.settings;openModal(`<h2>Attendance frequency rules</h2><p>Percentages start with the first complete, eligible event for each trap. Missing dates and partial lists never record absences. Manual codes apply when no percentage is available.</p><form id="frequencyForm"><div class="two"><label>Recent complete sessions<input name="window" type="number" min="1" max="100" step="1" value="${c.window}" required></label><label>Frequently: at least %<input name="frequent" type="number" min="1" max="100" value="${c.frequent}" required></label><label>Sometimes: at least %<input name="sometimes" type="number" min="1" max="99" value="${c.sometimes}" required></label><label>BT 1 cadence anchor (UTC)<input name="anchor1" type="date" value="${esc(c.anchors[1])}" required></label><label>BT 2 cadence anchor (UTC)<input name="anchor2" type="date" value="${esc(c.anchors[2])}" required></label></div><p>Below Sometimes = Rarely. Unknown means no percentage or manual code.</p><button class="primary">Save frequency rules</button></form>`);$('#frequencyForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f);if(+v.sometimes>=+v.frequent){toast('Frequently must exceed Sometimes.');return}commit(()=>state.attendanceLog.settings={window:+v.window,frequent:+v.frequent,sometimes:+v.sometimes,anchors:{1:v.anchor1,2:v.anchor2}});closeModal()}};
function csvCell(v){const s=String(v??'');return'"'+(/^[=+@\-]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"'}
exportCSV=function(){const rows=[['Alliance','Username','Player ID','Assigned trap','Row','X','Y','BT1 frequency','BT1 attended','BT1 eligible records','BT2 frequency','BT2 attended','BT2 eligible records'],...state.members.map(m=>{const s=slotBy(m.slot),c=s?Hive.coord(state,s):{},a=Hive.attendanceStats(state,m,1),b=Hive.attendanceStats(state,m,2);return[m.alliance||state.settings.alliance,m.name,m.playerId,m.trap,s?.row??'',c.x??'',c.y??'',a.label,a.attended,a.count,b.label,b.attended,b.count]})];download('bear-hive-roster.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};$('#csvBtn').onclick=()=>exportCSV();
$('#attendanceCSV').onclick=()=>{const rows=[['Date UTC','Trap','List complete','Alliance','Username','Player ID','Eligible','Attended'],...Object.values(state.attendanceLog.sessions).flatMap(r=>r.eligible.map(id=>{const m=state.members.find(m=>m.id===id);return[r.date,r.trap,r.complete,m?.alliance||'',m?.name||'Removed player',m?.playerId||'',true,r.attended.includes(id)]}))];download('bear-hive-attendance.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};
$('#shareBtn').onclick=()=>{openModal('<h2>Officer outputs</h2><div class="sheet-list"><button id="outputFind">Find player & copy move instructions</button><button id="outputCSV">Export roster & frequencies</button><button id="outputAttendance">Export attendance history</button><button id="outputPNG">Download map image</button></div>');$('#outputFind').onclick=()=>$('#findBtn').click();$('#outputCSV').onclick=()=>exportCSV();$('#outputAttendance').onclick=()=>$('#attendanceCSV').click();$('#outputPNG').onclick=()=>{closeModal();navigate('map');setTimeout(()=>{fit();exportPNG()},50)}};
function renderQueueTabs(){$$('[data-queue-trap]').forEach(b=>{b.classList.toggle('active',+b.dataset.queueTrap===state.operations.rosterGroup);b.onclick=()=>{const group=+b.dataset.queueTrap;selectedMember=null;setTool('select');if(group){activeTrap=String(group);$$('#trapTabs button').forEach(t=>t.classList.toggle('active',t.dataset.trap===activeTrap))}commit(()=>{state.operations.rosterGroup=group;if(group)state.operations.trap=group});fit()}})}
